//! Embedded SVG graphics, generated by `build.rs` from the asset folders (RF-25): each list
//! holds `(file name without extension, file data)`, sorted by name.

include!(concat!(env!("OUT_DIR"), "/asset_files.rs"));

/// Looks up an embedded file by name.
///
/// # Panics
/// If the file does not exist (a missing asset is a build error, not a runtime state).
pub fn get(files: &[(&'static str, &'static [u8])], name: &str) -> &'static [u8] {
    files
        .iter()
        .find(|(n, _)| *n == name)
        .map_or_else(|| panic!("asset `{name}.svg` missing"), |&(_, data)| data)
}
